// Rules for VALIDATION_CONSTRAINTS.md section 3 — node cardinality bounds.
// Boundary events are wired via parentNode, not sequence flow, so their
// incoming flow count is always 0 by construction. Recursive-flagged edges
// are excluded from counts to match the engine's `CanJoin = inputs - recursive`.
import { registerRule } from '../registry';
import { ValidationRule, ValidationIssue } from '../types';
import {
  buildLookup,
  getIncoming,
  getOutgoing,
  getFlowIncoming,
  getFlowOutgoing,
  getFamily,
  isForkGateway,
  isMergeGateway,
  labelOf,
} from '../helpers';

const rule_3_1_StartEventCardinality: ValidationRule = {
  id: '3.1',
  description: 'StartEvent must have 0 incoming and exactly 1 outgoing flow',
  scope: 'process',
  run: (_ctx, process) => {
    if (!process) return [];
    const lookup = buildLookup(process);
    const issues: ValidationIssue[] = [];
    for (const n of process.nodes) {
      if (getFamily(n.type) !== 'StartEvent') continue;
      const incoming = getFlowIncoming(lookup, n.id).length;
      const outgoing = getFlowOutgoing(lookup, n.id).length;
      if (incoming !== 0) {
        issues.push({
          severity: 'error',
          rule: '3.1',
          message: `${labelOf(n)} must have 0 incoming flows (found ${incoming}).`,
          nodeIds: [n.id],
        });
      }
      if (outgoing !== 1) {
        issues.push({
          severity: 'error',
          rule: '3.1',
          message: `${labelOf(n)} must have exactly 1 outgoing flow (found ${outgoing}).`,
          nodeIds: [n.id],
        });
      }
    }
    return issues;
  },
};
registerRule(rule_3_1_StartEventCardinality);

