const rule_3_3_ActivityCardinality: ValidationRule = {
  id: '3.3',
  description: 'Activity must have exactly 1 incoming and 1 outgoing flow',
  scope: 'process',
  run: (_ctx, process) => {
    if (!process) return [];
    const lookup = buildLookup(process);
    const issues: ValidationIssue[] = [];
    for (const n of process.nodes) {
      if (getFamily(n.type) !== 'Activity') continue;
      // Recursive edges DO count toward activity cardinality — a ScriptTask
      // looping back via a recursive-flagged edge still has exactly one
      // outgoing flow. The recursive filter only matters for merge-gateway
      // CanJoin semantics (rule 3.8).
      const incoming = getIncoming(lookup, n.id).length;
      const outgoing = getOutgoing(lookup, n.id).length;
      if (incoming !== 1) {
        issues.push({
          severity: 'error',
          rule: '3.3',
          message: `${labelOf(n)} must have exactly 1 incoming flow (found ${incoming}).`,
          nodeIds: [n.id],
        });
      }
      if (outgoing !== 1) {
        issues.push({
          severity: 'error',
          rule: '3.3',
          message: `${labelOf(n)} must have exactly 1 outgoing flow (found ${outgoing}).`,
          nodeIds: [n.id],
        });
      }
    }
    return issues;
  },
};
registerRule(rule_3_3_ActivityCardinality);

