const rule_3_7_GatewayForkCardinality: ValidationRule = {
  id: '3.7',
  description: 'Fork gateway (IsMerging=false) must have exactly 1 incoming and at least 1 outgoing flow',
  scope: 'process',
  run: (_ctx, process) => {
    if (!process) return [];
    const lookup = buildLookup(process);
    const issues: ValidationIssue[] = [];
    for (const n of process.nodes) {
      if (!isForkGateway(n)) continue;
      const incoming = getFlowIncoming(lookup, n.id).length;
      const outgoing = getFlowOutgoing(lookup, n.id).length;
      if (incoming !== 1) {
        issues.push({
          severity: 'error',
          rule: '3.7',
          message: `${labelOf(n)} must have exactly 1 incoming flow (found ${incoming}).`,
          nodeIds: [n.id],
        });
      }
      if (outgoing < 1) {
        issues.push({
          severity: 'error',
          rule: '3.7',
          message: `${labelOf(n)} must have at least 1 outgoing flow (found ${outgoing}).`,
          nodeIds: [n.id],
        });
      }
    }
    return issues;
  },
};
registerRule(rule_3_7_GatewayForkCardinality);

