import React from 'react';
import { ReactFlowProvider } from 'reactflow';
import Controller, { ControllerProps } from './Controller';
import { ErrorBoundary } from './components/ErrorBoundary';
import { ToastProvider } from './contexts/ToastContext';
import { registerNodes } from './utils/nodeRegistry';
import { registerBuiltInAdapters } from './utils/adapters';
import './styles/index.css';

// Public API ──────────────────────────────────────────────────────────────
export * from './types';
export type { ControllerProps, ProjectSnapshot } from './Controller';
export type { NodeRegistration, ExtensionHandler } from './utils/nodeRegistry';
export {
  registerNode,
  registerNodes,
  getNodeTypes,
  getPropertyRegistry,
  getEngineType,
  getExtensionHandler,
  getDefaultData,
  resolveEditorType,
  getHandledFields,
  getRegistry,
} from './utils/nodeRegistry';
export {
  registerAdapter,
  unregisterAdapter,
  setDefaultAdapter,
  getAdapter,
  getDefaultAdapter,
  listAdapters,
  detectAdapter,
  getSupportedExtensions,
  registerBuiltInAdapters,
  adaptersReady,
} from './utils/adapters';
export type { FormatAdapter, FormatId, ImportResult, ExportResult } from './utils/adapters';
export { default as Controller } from './Controller';
export { mockDmnFiles, type DmnDefinition } from './services/mockDmnService';
export { getLayoutedElements } from './utils/autoLayout';
export { validateDiagram, summarize, hasBlockingErrors, type ValidationIssue } from './utils/validation';

// Auto-register chronicle's built-in adapters (BPMN when enabled at build).
// Hosts adding non-built-in adapters (e.g. PSS) should call registerAdapter()
// themselves before mounting <WorkflowEditorWrapper />.
registerBuiltInAdapters();

/**
 * Wrapper component for the Workflow Editor providing the required React
 * contexts (ErrorBoundary, ToastProvider, ReactFlowProvider).
 *
 * `initialData` is the editor's native ProcessDefinition[] shape. Hosts
 * loading from a serialized format (PSS, BPMN, ...) should run the file
 * through the matching FormatAdapter's `import()` first.
 */
export const WorkflowEditorWrapper: React.FC<ControllerProps> = (props) => {
  const { customNodes, ...rest } = props;
  if (customNodes) registerNodes(customNodes);

  return (
    <ErrorBoundary>
      <ToastProvider>
        <ReactFlowProvider>
          <div style={{ width: '100%', height: '100%' }}>
            <Controller {...rest} customNodes={customNodes} />
          </div>
        </ReactFlowProvider>
      </ToastProvider>
    </ErrorBoundary>
  );
};

export default WorkflowEditorWrapper;
