import React from 'react';
import { createRoot, Root } from 'react-dom/client';
import {
  adaptersReady,
  getAdapter,
  registerBuiltInAdapters,
  WorkflowEditorWrapper,
  type ProjectSnapshot,
} from './cdn-entry';

type SavePayload = {
  content: string;
  projectName: string;
  snapshot: ProjectSnapshot;
  quit: boolean;
};

type MountOptions = {
  content: string;
  processName?: string;
  onBack?: () => void;
  onSave?: (payload: SavePayload) => Promise<void>;
};

type MountedEditor = {
  unmount: () => void;
};

const roots = new WeakMap<Element, Root>();

function projectNameFor(snapshot: ProjectSnapshot, fallback?: string): string {
  return snapshot.processes[0]?.name || fallback || snapshot.projectName || 'new-process';
}

async function mount(target: Element | string, options: MountOptions): Promise<MountedEditor> {
  registerBuiltInAdapters();
  await adaptersReady();

  const element = typeof target === 'string' ? document.querySelector(target) : target;
  if (!element) throw new Error(`Workflow editor target not found: ${String(target)}`);

  roots.get(element)?.unmount();

  const adapter = getAdapter('bpjs');
  if (!adapter) throw new Error('BPJS adapter is not registered.');

  const imported = adapter.import(options.content);
  const root = createRoot(element);
  roots.set(element, root);

  const save = async (snapshot: ProjectSnapshot, quit: boolean) => {
    const projectName = projectNameFor(snapshot, options.processName);
    const exported = adapter.export(snapshot.processes, projectName);
    await options.onSave?.({
      content: exported.content,
      projectName,
      snapshot,
      quit,
    });
  };

  root.render(
    <WorkflowEditorWrapper
      key={`${options.processName || 'process'}-${Date.now()}`}
      initialData={imported.processes}
      onBack={options.onBack}
      onSave={(snapshot) => save(snapshot, false)}
      onSaveAndQuit={(snapshot) => save(snapshot, true)}
      theme="light"
    />,
  );

  return {
    unmount: () => {
      root.unmount();
      roots.delete(element);
    },
  };
}

declare global {
  interface Window {
    ChronicleWorkflowEditor: {
      mount: typeof mount;
    };
  }
}

window.ChronicleWorkflowEditor = { mount };
