import { registerAdapter } from './registry';

export * from './types';
export {
    registerAdapter,
    unregisterAdapter,
    setDefaultAdapter,
    getAdapter,
    getDefaultAdapter,
    listAdapters,
    detectAdapter,
    getSupportedExtensions,
} from './registry';

// Build-time constant injected by vite's `define`. When false, the
// corresponding `if` block (and its `import()`) is dead-code-eliminated
// by esbuild/rollup, so the BPMN adapter is not bundled.
declare const __ADAPTER_BPMN__: boolean;
declare const __ADAPTER_BPJS__: boolean;

let _registered = false;
const _pendingPromises: Promise<unknown>[] = [];

/**
 * Register adapters built into chronicle-editor. Today this is just BPMN
 * (gated by build-time `__ADAPTER_BPMN__`). Hosts adding non-built-in
 * adapters (e.g. PSS) should call `registerAdapter` directly with their
 * adapter implementation — typically before mounting the editor.
 */
export function registerBuiltInAdapters(): void {
    if (_registered) return;
    _registered = true;

    if (typeof __ADAPTER_BPMN__ !== 'undefined' && __ADAPTER_BPMN__) {
        // Dynamic import enables build-time tree-shaking of unused adapters.
        const p = import('./bpmn').then(m => registerAdapter(m.bpmnAdapter));
        _pendingPromises.push(p);
    }

    if (typeof __ADAPTER_BPJS__ !== 'undefined' && __ADAPTER_BPJS__) {
        const p = import('./bpjs').then(m => registerAdapter(m.bpjsAdapter, { default: true }));
        _pendingPromises.push(p);
    }
}

/** Resolves once all dynamically-loaded adapters have registered. */
export function adaptersReady(): Promise<void> {
    return Promise.all(_pendingPromises).then(() => undefined);
}
