import { FormatAdapter, FormatId } from './types';

const adapters = new Map<FormatId, FormatAdapter>();
let defaultId: FormatId | null = null;

export function registerAdapter(adapter: FormatAdapter, options?: { default?: boolean }): void {
    adapters.set(adapter.id, adapter);
    if (options?.default || defaultId === null) {
        defaultId = adapter.id;
    }
}

export function unregisterAdapter(id: FormatId): void {
    adapters.delete(id);
    if (defaultId === id) {
        defaultId = adapters.keys().next().value ?? null;
    }
}

export function setDefaultAdapter(id: FormatId): void {
    if (!adapters.has(id)) {
        throw new Error(`Cannot set default: adapter "${id}" not registered.`);
    }
    defaultId = id;
}

export function getAdapter(id: FormatId): FormatAdapter | undefined {
    return adapters.get(id);
}

export function getDefaultAdapter(): FormatAdapter {
    if (!defaultId) {
        throw new Error('No format adapter registered. Register at least one adapter (e.g. pss) at startup.');
    }
    const adapter = adapters.get(defaultId);
    if (!adapter) {
        throw new Error(`Default adapter "${defaultId}" missing from registry.`);
    }
    return adapter;
}

export function listAdapters(): FormatAdapter[] {
    return Array.from(adapters.values());
}

/**
 * Auto-detect adapter for given content. Strategy:
 *   1. If file has known extension matching one adapter, prefer that adapter
 *      (still verified via detect()).
 *   2. Otherwise iterate all adapters and pick first whose detect() returns true.
 */
export function detectAdapter(content: string, fileName?: string): FormatAdapter | undefined {
    const ext = fileName ? extractExtension(fileName) : null;

    if (ext) {
        const byExt = listAdapters().filter(a => a.fileExtensions.includes(ext));
        for (const a of byExt) {
            if (a.detect(content, fileName)) return a;
        }
        // If exactly one adapter claims the extension and detect failed, still
        // return it — content sniffing for ambiguous JSON shapes is unreliable.
        if (byExt.length === 1) return byExt[0];
    }

    for (const a of listAdapters()) {
        if (a.detect(content, fileName)) return a;
    }
    return undefined;
}

function extractExtension(fileName: string): string | null {
    const lower = fileName.toLowerCase();
    const idx = lower.lastIndexOf('.');
    return idx >= 0 ? lower.slice(idx) : null;
}

/** Build a comma-joined list of supported extensions, e.g. ".bpjs, .json, .bpmn" */
export function getSupportedExtensions(): string[] {
    const set = new Set<string>();
    for (const a of listAdapters()) {
        a.fileExtensions.forEach(e => set.add(e));
    }
    return Array.from(set);
}
